import React, { useState } from "react";
import { supabase } from "../supabaseClient";

const LoginForm = ({ setIsAdmin }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    try {
      const { error: loginError } = await supabase.auth.signInWithPassword({
        email,
        password,
      });
      if (loginError) {
        setError("Invalid login credentials");
        return;
      }

      const { data: admins, error: adminErr } = await supabase
        .from("admins")
        .select("email")
        .eq("email", email)
        .limit(1);

      if (adminErr) {
        setError("Login succeeded but failed to verify admin");
        return;
      }
      if (!admins || admins.length === 0) {
        setError("You are not an admin");
        return;
      }
      setIsAdmin(true);
    } catch (err) {
      setError("Login failed");
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100">
      <form 
        className="bg-white p-8 rounded-lg shadow-lg w-full max-w-sm"
        onSubmit={handleLogin}
      >
        <h3 className="text-2xl font-semibold mb-6 text-center">Admin Login</h3>

        <label className="block mb-2 font-medium">Email</label>
        <input
          type="email"
          required
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="w-full p-2 mb-4 border rounded focus:outline-none focus:ring-2 focus:ring-blue-400"
        />

        <label className="block mb-2 font-medium">Password</label>
        <input
          type="password"
          required
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="w-full p-2 mb-6 border rounded focus:outline-none focus:ring-2 focus:ring-blue-400"
        />

        <button
          type="submit"
          className="w-full bg-blue-500 text-white py-2 rounded hover:bg-blue-600 transition"
        >
          Sign in
        </button>

        {error && (
          <div className="mt-4 text-red-500 font-medium text-center">{error}</div>
        )}
      </form>
    </div>
  );
};

export default LoginForm;
